/**
 * ==================================
 * # Chamadas relacionadas ao formulário de extrato
 * ==================================
 */

export async function updateExtrato(
    extratoId: string,
    fields: string[],
    formData: Record<string, any>,
    options?: { revision?: number | null },
) {
    const fieldsToUpdate: Record<string, any> = generatePayloadToSend(
        formData,
        resolveCalcFormPatchFieldKeys(fields),
    );
    const headers: Record<string, string> = {};
    if (options?.revision != null) {
        headers['If-Match'] = String(options.revision);
    }
    const res = await api.patch(`/api/lead-magnet/update/${extratoId}/`, fieldsToUpdate, {
        headers,
    });
    return res.data as { revision?: number; message?: string };
}

/**
 * ==================================
 * # Chamadas relacionadas aos comentários
 * ==================================
 */
export async function getAllComments(extratoId: string): Promise<Comments[]> {
    const res = await api.get(`/api/comentarios/extrato/${extratoId}`);

