import CalcForm from '@/components/Forms/CalcForm';
import { processFormData } from '@/functions/formaters/processFormData';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { isCPFOrCNPJValid } from '@/functions/verifiers/isCPFOrCNPJValid';
