import { cn } from '@/lib/utils';
import { COLORS, ELEVATION } from '@/design-system';

interface IOficioDetailsFormSectionProps {
    oficioId: string;
    oficioData: DetailedOficioProps;
    disableSubmitButton?: boolean;
    className?: string;
}

function OficioFormSectionPanel({
    title,
    children,
    className,
}: {
    title: string;
    children: React.ReactNode;
    className?: string;
}) {
    return (
        <section
            className={cn('rounded-2xl border p-4 md:p-5', className)}
            style={{
                background: COLORS.card,
                borderColor: COLORS.line,
                boxShadow: ELEVATION.surfaceRest,
            }}
        >
            <h2 className="mb-4 font-satoshi text-base font-bold text-foreground">{title}</h2>
            {children}
        </section>
    );
}

export function OficioDetailsFormSection({
    oficioId,
    oficioData,
    disableSubmitButton = false,
    className,
}: IOficioDetailsFormSectionProps) {
    const form = useCalculadoraForm({ validation: 'edit' });

    const updateOficio = useMutation({
        mutationFn: async (data: Partial<CvldFormInputsProps>) => {
            const updatedFields = Object.keys(form.formState.dirtyFields);
            await updateExtrato(oficioId, updatedFields, data);
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                sendToastMessage({
                    title: 'Não foi possível atualizar o extrato.',
                    type: 'error',
                });
            }
        },
        onSuccess: async () => {
            sendToastMessage({
                title: 'Dados do ofício atualizados.',
                type: 'success',
            });
            form.reset(undefined, { keepValues: true });
        },
    });

    const handleSubmit = async (data: Partial<CvldFormInputsProps>) => {
        const updatedFields = Object.keys(form.formState.dirtyFields);

        if (updatedFields.length === 0) {
