    // # Store
    // ==============
    const extratoId = useBrokerStore((store) => store.extratoId);

    // ==============
    // # React Query
    // ==============
    const { data: pageData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const collaboration = useCollaborationContext();
    const collaborationRef = useRef(collaboration);
    collaborationRef.current = collaboration;
    const calcLockSessionActiveRef = useRef(false);
    const calcLock = collaboration?.getSectionLock('calc_form') ?? null;
    const calcLockedByOther = collaboration?.isSectionLockedByOther('calc_form') ?? false;

    // ==============
    // # Constants
    // ==============
    const vigenteProposalData = pageData?.propostas?.find((p) => p.vigente);
    const isCalcFormCalculateButtonOutage =
        process.env.NEXT_PUBLIC_FF_OUTAGE_CALC_FORM_CALCULATE_BUTTON === 'true';

    // ==============
    // # Functions
    // ==============
    async function handleRefreshOficioData() {
        const updatingToastId = sendToastMessage({
            title: 'Atualizando dados do ofício.',
            type: 'loading',
        });
        try {
            await queryClient.refetchQueries({ queryKey: [QueryKeys.oficios.item, extratoId] });
            sendToastMessage({
                title: 'Dados do ofício atualizados.',
                type: 'success',
                previousToastId: updatingToastId,
            });
        } catch (error) {
            console.error('Erro ao atualizar dados do ofício:', error);
            sendToastMessage({
                title: 'Erro ao atualizar dados do ofício.',
                type: 'error',
                previousToastId: updatingToastId,
            });
        }
    }

    // mutation de alteração dos dados do oficio
    const updateOficio = useMutation({
        mutationFn: async ({
            data,
            fields,
        }: {
            data: Partial<CvldFormInputsProps>;
            fields: string[];
        }) => {
            return updateExtrato(pageData?.id as string, fields, data as any, {
                revision: pageData?.revision ?? null,
            });
        },
        onError: async (error) => {
            if (error instanceof AxiosError) {
                if (error.response?.status === 409) {
                    collaboration?.showRevisionConflict?.();
                    setWillRecalculate(false);
                    return;
                }
                sendToastMessage({
                    title:
                        error.response?.data.result.error ||
                        'Não foi possível atualizar o extrato.',
                    type: 'error',
                });
            }
            setWillRecalculate(false);
            await handleRefreshOficioData();
        },
        onSuccess: async () => {
            sendToastMessage({ title: 'Dados do ofício atualizados.', type: 'success' });
            if (calcLockSessionActiveRef.current) {
                collaborationRef.current?.releaseSectionLock('calc_form');
                calcLockSessionActiveRef.current = false;
            }

            await sleep(1.25);
            await handleRefreshOficioData();
            const fresh = queryClient.getQueryData<DetailedOficioProps>([
                QueryKeys.oficios.item,
                extratoId,
            ]);
            if (fresh) {
                resetFormFromOficio(fresh, form.reset);
                setDefaultFormValues(buildFormValuesFromOficio(fresh));
            } else {
                form.reset(undefined, { keepValues: true });
            }

