'use client';

import { NewBrokerAlert } from '@/components/Alert/NewBrokerAlert';
import { Dialog, DialogTrigger } from '@/components/ui/dialog';
import {
    ProductDialogContent,
    ProductDialogDescription,
    ProductDialogHeader,
    ProductDialogTitle,
    productDialogBodyClass,
} from '@/design-system';
import { QueryKeys } from '@/constants/query-keys';
import { processFormData } from '@/functions/formaters/processFormData';
import { reverificarExigenciasProposta } from '@/functions/propostas/reverificar-exigencias-proposta';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { isCPFOrCNPJValid } from '@/functions/verifiers/isCPFOrCNPJValid';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { updateExtrato } from '@/services/BrokerServices';
import { collectUpdatedFormFields } from '@/functions/broker/collectUpdatedFormFields';
import { isCalcFormRecalculationTrigger } from '@/functions/broker/resolveCalcFormPatchFieldKeys';
import {
    buildFormValuesFromOficio,
    resetFormFromOficio,
} from '@/functions/calcform/fillFormData';
import { useBrokerStore } from '@/store/useBroker';
import { useSupportModalStore } from '@/store/useSupportModalStore';
import { CvldFormInputsProps } from '@/types/cvldform';
import { DetailedOficioProps } from '@/types/oficio';
import queryClient from '@/utils/queryClient';
import {
    buildSmartblockPrecificacaoFeedback,
    extractPrecificacaoMessage,
    extractSemSmartblockReason,
    isSmartblockPrecificacaoIssue,
} from '@/utils/smartblock-precificacao-feedback';
import { useMutation, useQuery } from '@tanstack/react-query';
import { AxiosError } from 'axios';
import { X } from 'lucide-react';
import dynamic from 'next/dynamic';
import { ReactNode, useCallback, useEffect, useState } from 'react';
import { useCalculadoraForm } from '@/hooks/useCalculadoraForm';
import { useEditExtratoComparison } from '../_hooks/useEditExtratoComparison';
import { EditExtratoComparisonBanner } from './EditExtratoComparisonBanner';

const CalcForm = dynamic(() => import('@/components/Forms/CalcForm'), {
    ssr: false,
    loading: () => (
        <div className="flex min-h-[240px] items-center justify-center text-sm text-paragraph">
            Carregando formulário…
        </div>
    ),
});

interface EditExtratoModalProps {
    children: ReactNode;
}

export function EditExtratoModal({ children }: EditExtratoModalProps) {
    const [open, setOpen] = useState(false);
    const [defaultFormValues, setDefaultFormValues] = useState<any>(null);
    const [willRecalculate, setWillRecalculate] = useState<boolean>(false);

    // ==============
    // # Hook Form
    // ==============
    const form = useCalculadoraForm({ validation: 'edit' });
    const updatedFields = collectUpdatedFormFields(
        form.formState.dirtyFields as Record<string, unknown>,
    );
    const formValues = form.watch();

    // ==============
    // # Store
    // ==============
    const extratoId = useBrokerStore((store) => store.extratoId);

    // ==============
    // # React Query
    // ==============
    const { data: pageData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const comparison = useEditExtratoComparison({
        isOpen: open,
        oficioDetails: pageData,
    });

    // ==============
    // # Constants
    // ==============
    const vigenteProposal = pageData?.propostas?.find((p) => p.vigente);
    const isCalcFormCalculateButtonOutage =
        process.env.NEXT_PUBLIC_FF_OUTAGE_CALC_FORM_CALCULATE_BUTTON === 'true';

    // ==============
    // # Functions
    // ==============
    async function handleRefreshOficioData() {
        const updatingToastId = sendToastMessage({
            title: 'Atualizando dados do ofício.',
            type: 'loading',
        });
        try {
            await queryClient.refetchQueries({ queryKey: [QueryKeys.oficios.item, extratoId] });
            sendToastMessage({
                title: 'Dados do ofício atualizados.',
                type: 'success',
                previousToastId: updatingToastId,
            });
        } catch (error) {
            console.error('Erro ao atualizar dados do ofício:', error);
            sendToastMessage({
                title: 'Erro ao atualizar dados do ofício.',
                type: 'error',
                previousToastId: updatingToastId,
            });
        }
    }

    async function invalidateProposalQueries() {
        const proposalToastId = sendToastMessage({
            title: 'Atualizando dados da proposta.',
            type: 'loading',
        });
        await Promise.allSettled([
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.propostas.vigente, vigenteProposal?.uuid],
            }),
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.oficios.proposalList, extratoId],
            }),
        ])
            .then((res) => {
                const someFulfilled = res.some((result) => result.status === 'fulfilled');
                if (someFulfilled) {
                    sendToastMessage({
                        title: 'Dados da proposta atualizados.',
                        type: 'success',
                        previousToastId: proposalToastId,
                    });
                }
            })
            .catch(() => {
                sendToastMessage({
                    title: 'Erro ao atualizar dados da proposta.',
                    type: 'error',
                    previousToastId: proposalToastId,
                });
            });
    }

    // mutation de alteração dos dados do oficio
    const updateOficio = useMutation({
        mutationFn: async ({
            data,
            fields,
        }: {
            data: Partial<CvldFormInputsProps>;
            fields: string[];
        }) => {
            await updateExtrato(pageData?.id as string, fields, data as any);
        },
        onError: async (error) => {
            if (error instanceof AxiosError) {
                const errorPayload = error.response?.data;
                const errorMsg =
                    extractPrecificacaoMessage(errorPayload) ??
                    'Não foi possível atualizar o extrato.';
                const isSmartBlockError = isSmartblockPrecificacaoIssue(errorPayload);
                if (isSmartBlockError) {
                    const feedback = buildSmartblockPrecificacaoFeedback(
                        errorMsg,
                        extractSemSmartblockReason(errorPayload),
                    );
                    sendToastMessage({
                        ...feedback,
                        clickAction:
                            feedback.actionlabel === 'Abrir chamado'
                                ? () => useSupportModalStore.getState().openModal()
                                : undefined,
                    });
                } else {
                    sendToastMessage({
                        title: errorMsg,
                        type: 'error',
                    });
                }
            }
            setWillRecalculate(false);
            await handleRefreshOficioData();
        },
        onSuccess: async () => {
            sendToastMessage({ title: 'Dados do ofício atualizados.', type: 'success' });

            await handleRefreshOficioData();
            const fresh = queryClient.getQueryData<DetailedOficioProps>([
                QueryKeys.oficios.item,
                extratoId,
            ]);
            if (fresh) {
                resetFormFromOficio(fresh, form.reset);
                setDefaultFormValues(buildFormValuesFromOficio(fresh));

